[CmdletBinding()]param([string]$VCenter="VCENTER01",[int]$WarningAgeDays=3,[int]$CriticalAgeDays=7,[string]$OutputPath=".\vmware-snapshots.csv")
$n=Get-Date;try{Import-Module VMware.PowerCLI;Connect-VIServer $VCenter|Out-Null;$r=Get-VM|Get-Snapshot|%{$a=($n-$_.Created).Days;[pscustomobject]@{VM=$_.VM.Name;Snapshot=$_.Name;Created=$_.Created;AgeDays=$a;SizeGB=[math]::Round($_.SizeGB,2);Status=if($a-ge$CriticalAgeDays){"Critical"}elseif($a-ge$WarningAgeDays){"Warning"}else{"Healthy"}}};$r|Export-Csv $OutputPath -NoTypeInformation;$r}finally{Disconnect-VIServer * -Confirm:$false -ErrorAction SilentlyContinue}
